DELIMITER $$
USE `blood_bank`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `blood_bank`.`after_donation_insert`
AFTER INSERT ON `blood_bank`.`donations`
FOR EACH ROW
BEGIN
    UPDATE blood_inventory 
    SET units_available = units_available + NEW.units_donated
    WHERE blood_group = NEW.blood_group;
    
    UPDATE donors 
    SET last_donation_date = DATE(NEW.donation_date)
    WHERE donor_id = NEW.donor_id;
END$$


